1	#!/usr/bin/env bun
2	// PAI Obsidian Capture Server v2
3	// Unified capture webhook replacing ObsidianVoiceWebhook.ts
4	// Endpoints: POST /voice-note (iOS compat), POST /capture (text), POST /youtube, GET / (web UI)
5	// Port: 27337 — same as predecessor, drop-in replacement
6	
7	import { join } from 'path'
8	import { mkdir, unlink } from 'fs/promises'
9	import { existsSync, readFileSync } from 'fs'
10	import { spawnSync, spawn } from 'child_process'
11	
12	const PORT = parseInt(process.env.VOICE_WEBHOOK_PORT || '27337')
13	const VAULT = '/opt/docker/appdata/obsidian-jellybase/vault/OB_v2'
14	const INBOX = join(VAULT, '00 INBOX')
15	const YOUTUBE_VAULT = join(VAULT, '04 VAULT/YouTube')
16	const SECRET = process.env.VOICE_WEBHOOK_SECRET || ''
17	const YTDLP = process.env.YTDLP_PATH || '/home/jellypai/.local/bin/yt-dlp'
18	const YOUTUBE_TIMEOUT_MS = 45_000
19	const AI_TIMEOUT_MS = 75_000
20	
21	function isoDate(): string {
22	  return new Date().toISOString().slice(0, 10)
23	}
24	
25	function timestamp(): string {
26	  return new Date().toISOString().replace('T', ' ').slice(0, 16)
27	}
28	
29	function slugDate(): string {
30	  return new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-')
31	}
32	
33	function isYouTubeUrl(url: string): boolean {
34	  try {
35	    const u = new URL(url)
36	    return u.hostname === 'youtube.com' || u.hostname === 'www.youtube.com' ||
37	      u.hostname === 'youtu.be' || u.hostname === 'm.youtube.com'
38	  } catch {
39	    return false
40	  }
41	}
42	
43	// ── VTT parsing ──────────────────────────────────────────────────────────────
44	
45	interface VttSegment { seconds: number; text: string }
46	
47	function parseVttSegments(content: string): VttSegment[] {
48	  const lines = content.split('\n')
49	  const segments: VttSegment[] = []
50	  let currentSeconds = 0
51	  let prev = ''
52	
53	  for (const line of lines) {
54	    const trimmed = line.trim()
55	    if (!trimmed || trimmed === 'WEBVTT') continue
56	    if (/^(Kind|Language|NOTE|STYLE)[\s:]/.test(trimmed)) continue
57	
58	    const tsMatch = trimmed.match(/^(\d{2}):(\d{2}):(\d{2})\.\d+ -->/)
59	    if (tsMatch) {
60	      currentSeconds = parseInt(tsMatch[1]) * 3600 + parseInt(tsMatch[2]) * 60 + parseInt(tsMatch[3])
61	      continue
62	    }
63	
64	    const clean = trimmed.replace(/<[^>]+>/g, '').trim()
65	    if (!clean || clean === prev) continue
66	    segments.push({ seconds: currentSeconds, text: clean })
67	    prev = clean
68	  }
69	  return segments
70	}
71	
72	function vttToPlainText(segments: VttSegment[]): string {
73	  return segments.map(s => s.text).join(' ').trim().slice(0, 4000)
74	}
75	
76	function formatSeconds(s: number): string {
77	  const m = Math.floor(s / 60)
78	  const sec = s % 60
79	  return `${m}:${String(sec).padStart(2, '0')}`
80	}
81	
82	// Thins out segment density for the AI prompt (~every 3rd line with timestamps)
83	function vttForAI(segments: VttSegment[]): string {
84	  return segments
85	    .filter((_, i) => i % 3 === 0)
86	    .map(s => `[${formatSeconds(s.seconds)}/${s.seconds}s] ${s.text}`)
87	    .join('\n')
88	    .slice(0, 6000)
89	}
90	
91	// ── Process helpers ───────────────────────────────────────────────────────────
92	
93	function runProcess(cmd: string, args: string[], timeoutMs: number): Promise<{ stdout: string; stderr: string; code: number }> {
94	  return new Promise((resolve) => {
95	    let stdout = ''
96	    let stderr = ''
97	    const proc = spawn(cmd, args, { env: { ...process.env, PATH: `/home/jellypai/.local/bin:${process.env.PATH}` } })
98	    proc.stdout?.on('data', (d: Buffer) => { stdout += d.toString() })
99	    proc.stderr?.on('data', (d: Buffer) => { stderr += d.toString() })
100	    const timer = setTimeout(() => { proc.kill(); resolve({ stdout, stderr, code: -1 }) }, timeoutMs)
101	    proc.on('close', (code: number | null) => { clearTimeout(timer); resolve({ stdout, stderr, code: code ?? 0 }) })
102	  })
103	}
104	
105	const OPENCODE = '/home/jellypai/.bun/bin/opencode'
106	const OPENCODE_SERVER = 'http://localhost:7878'
107	
108	function getOpenCodePassword(): string {
109	  // Read OPENCODE_SERVER_PASSWORD from the opencode serve process environment.
110	  // The password is auto-generated at server start and stored in its proc env.
111	  try {
112	    const pg = spawnSync('pgrep', ['-f', 'opencode serve'], { encoding: 'utf8' })
113	    const pid = pg.stdout.trim().split('\n')[0]
114	    if (!pid) return process.env.OPENCODE_SERVER_PASSWORD || ''
115	    const envRaw = readFileSync(`/proc/${pid}/environ`, 'utf8')
116	    const match = envRaw.split('\0').find(e => e.startsWith('OPENCODE_SERVER_PASSWORD='))
117	    return match ? match.slice('OPENCODE_SERVER_PASSWORD='.length) : (process.env.OPENCODE_SERVER_PASSWORD || '')
118	  } catch {
119	    return process.env.OPENCODE_SERVER_PASSWORD || ''
120	  }
121	}
122	
123	async function runOpenCode(prompt: string): Promise<string> {
124	  // opencode run requires --attach + OPENCODE_SERVER_PASSWORD when spawned without a TTY;
125	  // the header line ("> build · model") goes to stderr, stdout is clean response text
126	  return new Promise((resolve) => {
127	    let stdout = ''
128	    const proc = spawn(
129	      OPENCODE,
130	      ['run', '--attach', OPENCODE_SERVER, '-m', 'openai/gpt-5.5', prompt],
131	      {
132	        env: {
133	          HOME: '/home/jellypai',
134	          PATH: `/home/jellypai/.local/bin:/home/jellypai/.bun/bin:/usr/local/bin:/usr/bin:/bin`,
135	          OPENCODE_SERVER_PASSWORD: getOpenCodePassword(),
136	        },
137	        stdio: ['ignore', 'pipe', 'pipe'],
138	      }
139	    )
140	    proc.stdout?.on('data', (d: Buffer) => { stdout += d.toString() })
141	    const timer = setTimeout(() => { proc.kill(); resolve('') }, AI_TIMEOUT_MS)
142	    proc.on('close', () => { clearTimeout(timer); resolve(stdout.trim()) })
143	  })
144	}
145	
146	// ── YouTube extraction ────────────────────────────────────────────────────────
147	
148	interface YouTubeMeta {
149	  title: string
150	  description: string
151	  channel: string
152	  durationString: string
153	  uploadDate: string
154	  thumbnail: string
155	  categories: string[]
156	  videoId: string
157	  segments: VttSegment[]
158	  transcriptOk: boolean
159	}
160	
161	function metaIsUsable(meta: YouTubeMeta): boolean {
162	  if (!meta.title.trim()) return false
163	  return meta.segments.length > 5 || meta.description.trim().length > 50
164	}
165	
166	async function extractYouTube(url: string): Promise<YouTubeMeta> {
167	  const empty: YouTubeMeta = {
168	    title: '', description: '', channel: '', durationString: '', uploadDate: isoDate(),
169	    thumbnail: '', categories: [], videoId: '', segments: [], transcriptOk: false,
170	  }
171	
172	  const metaResult = await runProcess(YTDLP, ['--dump-json', '--no-download', url], YOUTUBE_TIMEOUT_MS)
173	  if (metaResult.code !== 0 || !metaResult.stdout.trim()) return empty
174	
175	  let raw: any = {}
176	  try { raw = JSON.parse(metaResult.stdout) } catch { return empty }
177	
178	  const uploadDate = raw.upload_date
179	    ? `${raw.upload_date.slice(0, 4)}-${raw.upload_date.slice(4, 6)}-${raw.upload_date.slice(6, 8)}`
180	    : isoDate()
181	
182	  const thumbnail = (() => {
183	    if (Array.isArray(raw.thumbnails) && raw.thumbnails.length > 0) {
184	      // Prefer highest resolution
185	      return raw.thumbnails[raw.thumbnails.length - 1]?.url || raw.thumbnail || ''
186	    }
187	    return raw.thumbnail || ''
188	  })()
189	
190	  const meta: YouTubeMeta = {
191	    title: raw.title || '',
192	    description: (raw.description || '').slice(0, 2000),
193	    channel: raw.channel || raw.uploader || '',
194	    durationString: raw.duration_string || '',
195	    uploadDate,
196	    thumbnail,
197	    categories: Array.isArray(raw.categories) ? raw.categories : [],
198	    videoId: raw.id || '',
199	    segments: [],
200	    transcriptOk: false,
201	  }
202	
203	  // Extract subtitles
204	  const tmpBase = `/tmp/yt-${Date.now()}`
205	  const subResult = await runProcess(
206	    YTDLP,
207	    ['--write-auto-sub', '--skip-download', '--sub-format', 'vtt',
208	      '--sub-lang', 'en', '--output', `${tmpBase}.%(ext)s`, url],
209	    YOUTUBE_TIMEOUT_MS
210	  )
211	
212	  if (subResult.code === 0) {
213	    for (const candidate of [`${tmpBase}.en.vtt`, `${tmpBase}.en-orig.vtt`]) {
214	      if (existsSync(candidate)) {
215	        const vttRaw = await Bun.file(candidate).text()
216	        unlink(candidate).catch(() => {})
217	        meta.segments = parseVttSegments(vttRaw)
218	        meta.transcriptOk = meta.segments.length > 0
219	        break
220	      }
221	    }
222	  }
223	
224	  return meta
225	}
226	
227	// ── AI analysis ───────────────────────────────────────────────────────────────
228	
229	async function analyzeYouTube(meta: YouTubeMeta, url: string): Promise<string> {
230	  const transcriptBlock = meta.transcriptOk
231	    ? vttForAI(meta.segments)
232	    : `(No captions available)\n\nDescription:\n${meta.description.slice(0, 1000)}`
233	
234	  const system = 'You are a precise video analyst. Generate clean Markdown analysis in the exact sections requested. No preamble, no explanation outside the sections, no meta-commentary.'
235	
236	  const user = `YouTube video:
237	Title: ${meta.title}
238	Channel: ${meta.channel}
239	Published: ${meta.uploadDate}
240	${meta.description ? `Description: ${meta.description.slice(0, 400)}\n` : ''}
241	Transcript (format [MM:SS/total_seconds] text):
242	${transcriptBlock}
243	
244	Generate these sections in exact order with these exact headings:
245	
